{% extends "base.html" %}
{% block content %}
  <h1>Игры</h1>

  {# action/method оставлены рабочими: без JS форма просто перезагружает /games.
     С htmx тот же набор полей уходит на /games/fragment и подменяет только список,
     а адресную строку правит заголовок HX-Push-Url из ответа. #}
  <form class="filters" action="/games" method="get"
        hx-get="/games/fragment" hx-target="#games-results" hx-swap="innerHTML"
        hx-trigger="submit, keyup changed delay:300ms from:#q, change from:#platform, change from:#sort">
    <input type="search" id="q" name="q" value="{{ q }}" placeholder="Поиск по названию"
           autocomplete="off">
    <select id="platform" name="platform">
      <option value="">Все платформы</option>
      {% for p in all_platforms %}
        <option value="{{ p.platform_slug }}" {{ 'selected' if p.platform_slug == platform }}>
          {{ p.platform_name }} ({{ p.games_count }})
        </option>
      {% endfor %}
    </select>
    <select id="sort" name="sort">
      <option value="new" {{ 'selected' if sort == 'new' }}>Сначала новые</option>
      <option value="metascore" {{ 'selected' if sort == 'metascore' }}>По Metascore</option>
      <option value="userscore" {{ 'selected' if sort == 'userscore' }}>По Userscore</option>
    </select>
    {# Пагинация всегда начинается заново, когда меняются поиск, фильтр или порядок. #}
    <noscript><button type="submit">Показать</button></noscript>
  </form>

  <div id="games-results">{% include "_games_fragment.html" %}</div>

  <style>
    .filters { display:flex; gap:10px; flex-wrap:wrap; margin:0 0 18px; }
    .filters input, .filters select { font:inherit; padding:7px 10px; border-radius:8px;
                                      border:1px solid var(--line); background:var(--card); color:var(--fg); }
    .filters input { flex:1 1 260px; min-width:180px; }
    .total, .empty { margin:0 0 14px; }
    .cards { list-style:none; margin:0; padding:0;
             display:grid; gap:16px; grid-template-columns:repeat(auto-fill, minmax(180px, 1fr)); }
    .card { background:var(--card); border:1px solid var(--line); border-radius:10px; overflow:hidden;
            display:flex; flex-direction:column; }
    .card .cover { display:block; aspect-ratio:226/332; background:var(--line); }
    .card .cover img { width:100%; height:100%; object-fit:cover; display:block; }
    .cover-empty { display:flex; height:100%; align-items:center; justify-content:center; font-size:13px; }
    .card .body { padding:10px 12px 12px; display:flex; flex-direction:column; gap:6px; }
    .card .title { font-weight:600; text-decoration:none; line-height:1.3; }
    .card .platforms, .card .scores { margin:0; font-size:13px; }
    .score { display:inline-block; min-width:30px; padding:2px 6px; border-radius:5px;
             font-weight:600; text-align:center; color:#111; }
    .metascore { background:#ffcc33; }
    .userscore { background:#7ec8a0; }
    .pager { display:flex; gap:16px; margin:22px 0 0; font-size:14px; }
  </style>
{% endblock %}

